const existing = new Set(($("Aggregate IDs").first().json.ids) || []);
let arr = [];
const resp = await this.helpers.httpRequest({ url: "https://raw.githubusercontent.com/SimplifyJobs/Summer2027-Internships/dev/.github/scripts/listings.json", json: true, timeout: 30000 });
arr = Array.isArray(resp) ? resp : [];
const BAD = ["canada", ", on", ", bc", ", qc", ", ab", ", ns", "toronto", "vancouver", "montreal", "ottawa", "united kingdom", "london", "india", "ireland", "germany", "france", "spain", "singapore", "australia"];
const out = [];
for (const e of arr) {
  if (!e || e.active !== true || e.is_visible === false) continue;
  const cat = String(e.category || "").toLowerCase();
  const catOk = cat.includes("software") || cat.includes("ai/ml") || cat.includes("machine learning") || cat.includes("data science") || cat.includes("data");
  if (!catOk) continue;
  const terms = (Array.isArray(e.terms) ? e.terms.join(" ") : String(e.terms || "")).toLowerCase();
  if (!terms.includes("summer 2027")) continue;
  const locArr = Array.isArray(e.locations) ? e.locations : [e.locations];
  const loc = locArr.filter(Boolean).join("; ");
  const locL = loc.toLowerCase();
  if (BAD.some(b => locL.includes(b))) continue;
  const id = String(e.id || e.url || "");
  if (!id || existing.has(id)) continue;
  const posted = e.date_posted ? new Date(e.date_posted * 1000).toISOString() : null;
  const meta = "Category: " + (e.category || "n/a") + ". Terms: " + (Array.isArray(e.terms) ? e.terms.join(", ") : "n/a") + ". Sponsorship: " + (e.sponsorship || "n/a") + ". Degrees: " + ((Array.isArray(e.degrees) ? e.degrees.join(", ") : "") || "n/a") + ".";
  out.push({ json: { source: "simplify", external_id: id, company: e.company_name || "", title: e.title || "", location: loc, url: e.url || e.company_url || "", description: meta, posted_at: posted, _sort: e.date_posted || 0 } });
}
out.sort((a, b) => b.json._sort - a.json._sort);
const top = out.slice(0, 40);
for (const o of top) { delete o.json._sort; }
return top;

const j = $input.item.json;
const profile = "Victor is a data-science/AI engineer looking for a SUMMER 2027 internship in the UNITED STATES.
Background: builds AI/data products at Canal+/BCE (media and broadcasting); focus on LLMs plus structured data; student in an AI dual-degree (ESSEC / CentraleSupelec).
STRONG match: AI/ML engineering internships at (a) media/broadcasting/streaming companies (his Canal+ experience is a direct edge), (b) genuine AI labs/companies, (c) major software and cloud companies, (d) AI-tooling companies.
DECENT: AI/ML/data internship roles at companies that are not AI-centred.
SKIP: non-technical roles, senior or full-time-only roles, non-US locations, anything unrelated to software/AI/ML/data.";
const rubric = "You are given limited metadata (company, title, location, category) rather than a full description. Judge fit on that.
Score how well THIS role fits Victor, 0-100, and pick a severity.
severity: strong (>=75, worth an instant alert), decent (45-74, worth tracking), skip (<45).
Penalize heavily if: not US, not an internship, or not software/AI/ML/data.
Return ONLY compact JSON with keys fit_score (int 0-100), severity (strong|decent|skip), why (one sentence, max 25 words).";
const user = "Company: " + j.company + "
Title: " + j.title + "
Location: " + j.location + "
Details: " + j.description;
// 1200 not 300: gpt-oss-120b reasons before answering; at 300 Groq's JSON mode failed with "max completion tokens reached" (~7% of calls).
const payload = { model: "openai/gpt-oss-120b", temperature: 0.2, max_tokens: 1200, response_format: { type: "json_object" }, messages: [ { role: "system", content: profile + "

" + rubric }, { role: "user", content: user } ] };
return { json: Object.assign({}, j, { body: JSON.stringify(payload) }) };

const r = $input.item.json;
const j = $("Build Score Request").item.json;
const base = { source: j.source, external_id: j.external_id, company: j.company, title: j.title, location: j.location, url: j.url, description: j.description, posted_at: j.posted_at };
// A failed call (HTTP error item, empty or unparseable content) is NOT a verdict.
// Write the app's "unscored" state (all null) so the row is findable with `fit_score is null` and can be re-scored.
const unscored = { fit_score: null, severity: null, why: null };
if (r.error) return { json: Object.assign(base, unscored) };
let content = "";
try { content = r.choices[0].message.content || ""; } catch (e) {}
let p = null;
if (content) { try { p = JSON.parse(content); } catch (e) { const m = content.match(/\{[\s\S]*\}/); if (m) { try { p = JSON.parse(m[0]); } catch (e2) {} } } }
if (!p || typeof p !== "object") return { json: Object.assign(base, unscored) };
let score = Number(p.fit_score);
const sevOk = ["strong", "decent", "skip"].includes(p.severity);
if (!isFinite(score) && !sevOk) return { json: Object.assign(base, unscored) };
if (!isFinite(score)) score = p.severity === "strong" ? 75 : p.severity === "decent" ? 45 : 0;
score = Math.max(0, Math.min(100, Math.round(score)));
const sev = sevOk ? p.severity : score >= 75 ? "strong" : score >= 45 ? "decent" : "skip";
return { json: Object.assign(base, { fit_score: score, severity: sev, why: String(p.why || "").slice(0, 300) }) };
